import React, { useState } from 'react';

const QuizPage = () => {
  const [formData, setFormData] = useState({
    exam: "",
    difficultyLevels: [],
    classYear: "",
    name: "",
    quizMode: "",
    addHints: false,
    answerExplanation: false,
    breakIntoSubtopics: false,
    subjects: [],
    topics: [],
    currentSubject: "",
    currentTopic: "",
    numberOfQuestions: null,
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    console.log(formData);
  };

  const handleAddSubject = () => {
    if (formData.currentSubject.trim()) {
      setFormData((prev) => ({
        ...prev,
        subjects: [...prev.subjects, formData.currentSubject.trim()],
        currentSubject: "",
      }));
    }
  };

  const handleAddTopic = () => {
    if (formData.currentTopic.trim()) {
      setFormData((prev) => ({
        ...prev,
        topics: [...prev.topics, formData.currentTopic.trim()],
        currentTopic: "",
      }));
    }
  };

  const [timerOption, setTimerOption] = useState("noTimer");
  const [perQuestionTime, setPerQuestionTime] = useState("");
  const [totalTime, setTotalTime] = useState("");

  const handleTimerChange = (e) => {
    setTimerOption(e.target.value);
    setPerQuestionTime("");
    setTotalTime("");
  };

  return (
    <div className="p-8 bg-gray-100 min-h-screen">
      <div className="max-w-4xl mx-auto bg-white shadow-md rounded-lg p-6">
        <h1 className="text-3xl font-semibold text-center text-gray-800 mb-6">Create Your Quiz</h1>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label htmlFor="name" className="block font-medium text-gray-700">
              Your Name
            </label>
            <input
              type="text"
              id="name"
              name="name"
              placeholder="e.g. ABC XYZ"
              value={formData.name}
              onChange={handleChange}
              required
              className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
            />
          </div>

          <div>
            <label htmlFor="exam" className="block font-medium text-gray-700">
              Exam Type
            </label>
            <input
              type="text"
              id="exam"
              name="exam"
              placeholder="e.g. MidTerm, JEE"
              value={formData.exam}
              onChange={handleChange}
              className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
            />
          </div>

          <div>
            <label htmlFor="numberOfQuestions" className="block font-medium text-gray-700">
              Number of Questions
            </label>
            <input
              type="number"
              id="numberOfQuestions"
              name="numberOfQuestions"
              placeholder="e.g. 5, 10"
              value={formData.numberOfQuestions}
              onChange={handleChange}
              className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring focus:ring-blue-300"
            />
          </div>

          <div>
            <span className="block font-medium text-gray-700">Difficulty Levels</span>
            <div className="flex space-x-4 mt-2">
              {["Easy", "Medium", "Hard"].map((level) => (
                <label key={level} className="inline-flex items-center">
                  <input
                    type="checkbox"
                    value={level}
                    checked={formData.difficultyLevels.includes(level)}
                    onChange={handleDifficultyChange}
                    className="text-blue-500 focus:ring focus:ring-blue-300"
                  />
                  <span className="ml-2 text-gray-700">{level}</span>
                </label>
              ))}
            </div>
          </div>

          <div>
            <h3 className="block font-medium text-gray-700 mb-2">Subjects</h3>
            <div className="flex items-center space-x-4">
              <input
                type="text"
                name="currentSubject"
                value={formData.currentSubject}
                onChange={(e) =>
                  setFormData({ ...formData, currentSubject: e.target.value })
                }
                placeholder="Enter subject"
                className="w-full p-2 border rounded-md focus:ring focus:ring-blue-300"
              />
              <button
                type="button"
                onClick={handleAddSubject}
                className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 focus:outline-none"
              >
                Add
              </button>
            </div>
            <div className="flex flex-wrap gap-2 mt-2">
              {formData.subjects.map((subject, index) => (
                <span
                  key={index}
                  className="bg-blue-200 text-blue-800 px-3 py-1 rounded-lg text-sm"
                >
                  {subject}
                </span>
              ))}
            </div>
          </div>

          <button
            type="submit"
            className="block w-full bg-green-500 hover:bg-green-600 text-white font-bold py-3 rounded-lg shadow-lg transition"
          >
            Create Quiz
          </button>
        </form>
      </div>
    </div>
  );
};

export default QuizPage;
